use std::{fs,path::{Path,PathBuf},collections::BTreeMap,fmt::Write,process::Command,io::Read};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-base-census";const REPORT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-base-census";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),out)}else if e.file_type().unwrap().is_file(){out.push(e.path());}}}
fn state(result:Value){let mut s=read("/tmp/zopro-latest-optimization-status.json");s["experiment"]=result.clone();s["current_work"]=json!({"root":R,"phase":"Base-equality census complete; no source adoption or proof timing","owned_live_jobs":[],"production_accepted_unchanged":true,"new_cloud_resources":false});s["owned_live_jobs"]=json!([]);s["status"]=json!("Base census complete; inspect counts before next arithmetic design; goal active/unmet");s["next_step"]=json!("Inspect base census exact/signed row removals on activequeries. Material duplicate populations permit resource-admitted index-plan prototype; low populations close this direction for these keys. No universal shifted tables or repeated rejected pool variants. Original all-eightCPU10x active/unmet,prior5958 unchanged.");if let Some(c)=result.get("commit"){s["latest_pushed_commit"]=c.clone();}save("/tmp/zopro-latest-optimization-status.json",&s);let mut v=read("/tmp/zopro-validation-checkpoint/state.json");v["latest_base_census"]=result.clone();v["current_experiment"]=result;v["current_work"]=s["current_work"].clone();v["next_step"]=s["next_step"].clone();v["owned_live_jobs"]=json!([]);v["goal_achieved"]=json!(false);v["last_goal_turn_classification"]=json!("progress: exact signed-base opportunity census on nine current keys, independently tested, reported");save("/tmp/zopro-validation-checkpoint/state.json",&v);}
fn close(){let r=Path::new(R);assert_eq!(read(r.join("run/result.json"))["status"],"complete");for(p,h)in read(r.join("input-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let log=fs::read_to_string(r.join("run/census/stdout.log")).unwrap();assert!(log.lines().last().unwrap().starts_with("COMPLETE nineimages45querycounts"));let rows:Vec<Value>=log.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|l|serde_json::from_str(l).unwrap()).collect();assert_eq!(rows.len(),9);let mut max=0f64;let mut t=String::from("# Equal and opposite proving-key bases\n\nThis read-only census tests whether repeated bases could remove online point work by adding their scalars before MSM. It uses all nine current accepted Euler images and the unchanged accepted loader/libraries. No prover source, proof latency or memory policy changes.\n\nEvery scanned point is checked on curve; compressed negation must flip exactly its sign bit. A normalized compressed class records which signs occurred. Exact classes equal signed classes plus classes seen with both signs. Identity points are excluded from potential new arithmetic savings because the existing stream already skips them. The combinedK/H row is a count model for a shared linear sum; only the existing small fused query geometry is marked, and geometry alone does not establish runtime eligibility.\n\n|Shape|Query|Rows|Identities|Exact classes|Signed classes|Potential signed row removals|Fraction of nonidentity rows|\n|---|---|---:|---:|---:|---:|---:|---:|\n");for row in &rows{assert_eq!(row["accepted_loader_validated"],true);assert_eq!(row["queries"].as_array().unwrap().len(),5);for q in row["queries"].as_array().unwrap(){let s=&q["stats"];let f=s["signed_removal_fraction_nonidentity"].as_f64().unwrap();if q["query"]!="combined_KH_G1"||q["fused_size_geometry"]==true{max=max.max(f);}writeln!(t,"|{}|{}|{}|{}|{}|{}|{}|{:.6}%|",row["shape"].as_str().unwrap(),q["query"].as_str().unwrap(),s["rows"],s["identity_rows"],s["exact_point_classes"],s["signed_point_classes"],s["signed_total_removals"],100.*f).unwrap();}}
 let result=json!({"status":"complete key-only signed-base census","root":R,"report":format!("{REPORT}/README.md"),"images":9,"query_counts":45,"max_potential_signed_row_reduction_fraction":max,"new_SDK_proofs":0,"new_Gnark_exports":0,"prior_proof_count":5958,"tests":4,"production_170_sources_unchanged":true,"adopted":false,"goal_achieved":false,"new_cloud_resources":false,"rows":rows});save(r.join("results.json"),&result);
 writeln!(t,"\nMaximum counted potential removal among separate queries and size-eligible fusedK/H rows is{:.6}%. Counts are an optimistic arithmetic opportunity before scalar aggregation, indexing, startup and memory costs. They do not establish a speedup or a universal circuit property. Cross-query removals and map capacities are retained in [results](artifacts/results.json).\n",100.*max).unwrap();t.push_str("Four tests pass: signed/exact counters against independently sorted point encodings; G1/G2 signed-scalar combination against generator oracles; identity-only inputs; checked range/overflow/truncation handling. The accepted loader validates each whole image before scans following the pinned current format source. Points are decoded in4096-point tiles. Temporary hash maps grow with distinct points and are diagnostic-only. Process resource receipts include loading, mapped pages, point checks and maps, not minimum proving RAM.\n\nNo witness solve, SDK proof, Gnark export, CPU latency/profile or AWS run is added. Prior verified proof count5958 stays unchanged. No M5 speedup is newly measured; [last all-nine full SDK comparison](../2026-10-26-prefix-pool/README.md) retains CPU/Metal reference tables, and [latest stage diagnostic](../2026-10-26-prefix-stages/README.md) explains the query critical path. Neither establishes the original all-eight CPU10× goal. No source is adopted.\n\n[Protocol](artifacts/design.md), [driver](artifacts/probe.rs), [input hashes](artifacts/input-pins.json), [raw output](artifacts/run/census/stdout.log), [resource receipt](artifacts/run/census/stderr.log), [tests](artifacts/run/tests/stdout.log) and [artifact index](artifacts/artifact-index.json) retain evidence. Keys/libraries/executables remain local with hashes.\n");let dest=Path::new(REPORT).join("artifacts");fs::create_dir_all(&dest).unwrap();fs::write(Path::new(REPORT).join("README.md"),t).unwrap();let mut files=Vec::new();walk(&r.join("run"),&mut files);for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}let mut index=BTreeMap::new();for p in files{let ext=p.extension().and_then(|e|e.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"){continue;}let rel=p.strip_prefix(r).unwrap();let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();index.insert(rel.display().to_string(),hash(&target));}for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}save(dest.join("artifact-index.json"),&json!({"sha256":index}));state(result);println!("Closed9images45queries;maxremoval{max};{}artifacthashes",index.len());}
fn pushed(){let o=Command::new("git").args(["rev-parse","HEAD"]).output().unwrap();assert!(o.status.success());let commit=String::from_utf8(o.stdout).unwrap().trim().to_owned();let o=Command::new("git").args(["-c","url.https://github.com/.insteadOf=git@github.com:","-c","credential.helper=!gh auth git-credential","ls-remote","origin","refs/heads/sergei/zopro-cpu-perf"]).output().unwrap();assert!(o.status.success());assert_eq!(String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap(),commit);let mut result=read(Path::new(R).join("results.json"));result["commit"]=json!(commit);result["remote_verified"]=json!(true);state(result);}
fn main(){match std::env::args().nth(1).as_deref(){Some("close")=>close(),Some("pushed")=>pushed(),_=>panic!("mode")}}
